import json

def solve():
    houses = [1, 2, 3, 4, 5]
    categories = ["Name", "nationality", "vacation", "education", "occupation"]
    values = {
        "Name": ["Eric", "Peter", "Alice", "Bob", "Arnold"],
        "nationality": ["norwegian", "brit", "swede", "dane", "german"],
        "vacation": ["cruise", "mountain", "camping", "beach", "city"],
        "education": ["bachelor", "master", "associate", "doctorate", "high school"],
        "occupation": ["artist", "doctor", "engineer", "teacher", "lawyer"],
    }

    # Initialize assignment and used values
    assignment = {(h, c): None for h in houses for c in categories}
    used = {c: set() for c in categories}

    # Pre-assign from explicit clues:
    # 17. The person who enjoys mountain retreats is in the fifth house.
    assignment[(5, "vacation")] = "mountain"
    used["vacation"].add("mountain")
    # 19. The person with a bachelor's degree is in the third house.
    assignment[(3, "education")] = "bachelor"
    used["education"].add("bachelor")

    def pos(cat, val):
        for h in houses:
            if assignment[(h, cat)] == val:
                return h
        return None

    def check_equal(cat1, val1, cat2, val2):
        p1 = pos(cat1, val1)
        p2 = pos(cat2, val2)
        if p1 is not None and p2 is not None and p1 != p2:
            return False
        return True

    def check_left_of(cat_left, val_left, cat_right, val_right):
        pL = pos(cat_left, val_left)
        pR = pos(cat_right, val_right)
        if pL is not None and pR is not None:
            return pL < pR
        if pL is not None and pR is None:
            # If left element is at far right, cannot have someone to its right
            if pL == 5:
                return False
        if pL is None and pR is not None:
            # If right element is at far left, cannot have someone to its left
            if pR == 1:
                return False
        return True

    def check_immediately_left_of(cat_left, val_left, cat_right, val_right):
        pL = pos(cat_left, val_left)
        pR = pos(cat_right, val_right)
        if pL is not None and pR is not None:
            return pL + 1 == pR
        if pL is not None and pR is None:
            if pL == 5:
                return False
        if pL is None and pR is not None:
            if pR == 1:
                return False
        return True

    def check_next_to(cat1, val1, cat2, val2):
        p1 = pos(cat1, val1)
        p2 = pos(cat2, val2)
        if p1 is not None and p2 is not None:
            return abs(p1 - p2) == 1
        return True

    def check_constraints():
        # 1. The person who likes going on cruises is the person who is a lawyer.
        if not check_equal("vacation", "cruise", "occupation", "lawyer"):
            return False
        # 2. The person who loves beach vacations is directly left of Arnold.
        if not check_immediately_left_of("vacation", "beach", "Name", "Arnold"):
            return False
        # 3. The person with a doctorate is somewhere to the left of Bob.
        if not check_left_of("education", "doctorate", "Name", "Bob"):
            return False
        # 4. The person with an associate's degree is the person who likes going on cruises.
        if not check_equal("education", "associate", "vacation", "cruise"):
            return False
        # 5. Peter is not in the first house.
        p = pos("Name", "Peter")
        if p is not None and p == 1:
            return False
        # 6. The person who is an artist is Peter.
        if not check_equal("occupation", "artist", "Name", "Peter"):
            return False
        # 7. The person who enjoys camping trips is the person with a master's degree.
        if not check_equal("vacation", "camping", "education", "master"):
            return False
        # 8. The Dane is somewhere to the right of the person who is a doctor.
        if not check_left_of("occupation", "doctor", "nationality", "dane"):
            return False
        # 9. The person with an associate's degree is directly left of the person who is an engineer.
        if not check_immediately_left_of("education", "associate", "occupation", "engineer"):
            return False
        # 10. The person who enjoys camping trips is the British person.
        if not check_equal("vacation", "camping", "nationality", "brit"):
            return False
        # 11. The Norwegian and the person with a bachelor's degree are next to each other.
        if not check_next_to("nationality", "norwegian", "education", "bachelor"):
            return False
        # 12. The person who is an artist is the Swedish person.
        if not check_equal("occupation", "artist", "nationality", "swede"):
            return False
        # 13. Bob is not in the fourth house.
        p = pos("Name", "Bob")
        if p is not None and p == 4:
            return False
        # 14. The person who enjoys camping trips is Eric.
        if not check_equal("vacation", "camping", "Name", "Eric"):
            return False
        # 15. Alice is the German.
        if not check_equal("Name", "Alice", "nationality", "german"):
            return False
        # 16. The person who loves beach vacations is somewhere to the left of the person who prefers city breaks.
        if not check_left_of("vacation", "beach", "vacation", "city"):
            return False
        # 17. The person who enjoys mountain retreats is in the fifth house.
        p = pos("vacation", "mountain")
        if p is not None and p != 5:
            return False
        # 18. The person who likes going on cruises is somewhere to the right of the person who loves beach vacations.
        if not check_left_of("vacation", "beach", "vacation", "cruise"):
            return False
        # 19. The person with a bachelor's degree is in the third house.
        p = pos("education", "bachelor")
        if p is not None and p != 3:
            return False

        return True

    # Variable ordering: use MRV (minimum remaining values) heuristic
    all_vars = [(h, c) for h in houses for c in categories if assignment[(h, c)] is None]

    def domain(h, c):
        # Allowed values are those not used in category
        vals = [v for v in values[c] if v not in used[c]]
        # Simple per-variable pruning
        if c == "Name":
            # 5. Peter is not in the first house.
            if h == 1 and "Peter" in vals:
                vals.remove("Peter")
            # 13. Bob is not in the fourth house.
            if h == 4 and "Bob" in vals:
                vals.remove("Bob")
        return vals

    solution_found = [False]

    def select_unassigned_variable():
        unassigned = [(h, c) for h, c in all_vars if assignment[(h, c)] is None]
        # MRV: choose var with fewest legal values
        best = None
        best_size = None
        best_domain = None
        for var in unassigned:
            d = domain(var[0], var[1])
            # Try to filter with immediate consistency check
            filtered = []
            for v in d:
                assignment[var] = v
                used[var[1]].add(v)
                ok = check_constraints()
                used[var[1]].remove(v)
                assignment[var] = None
                if ok:
                    filtered.append(v)
            dsize = len(filtered)
            if best is None or dsize < best_size:
                best = var
                best_size = dsize
                best_domain = filtered
            if dsize == 0:
                # fail fast
                return var, []
        return best, best_domain

    def backtrack():
        if all(assignment[(h, c)] is not None for h in houses for c in categories):
            # All assigned
            if check_constraints():
                solution_found[0] = True
                return True
            return False

        var, dom = select_unassigned_variable()
        if dom is None:
            dom = domain(var[0], var[1])
        for v in dom:
            assignment[var] = v
            used[var[1]].add(v)
            if check_constraints():
                if backtrack():
                    return True
            used[var[1]].remove(v)
            assignment[var] = None
        return False

    backtrack()

    # Build output
    header = ["House", "Name", "nationality", "vacation", "education", "occupation"]
    rows = []
    for h in houses:
        row = [str(h)]
        for c in header[1:]:
            row.append(assignment[(h, c)])
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result))
